1: /**
2:  * Auth Utility — JWT Token Management
3:  *
4:  * Centralizes token storage, retrieval, and authenticated fetch calls.
5:  * All frontend components should use `authFetch()` instead of raw `fetch()`
6:  * for any request to protected backend endpoints.
7:  */
8: 
9: const TOKEN_KEY = 'authToken';
10: 
11: /** Store the JWT token received from login/register */
12: export function setToken(token: string): void {
13:   localStorage.setItem(TOKEN_KEY, token);
14: }
15: 
16: /** Retrieve the stored JWT token */
17: export function getToken(): string | null {
18:   return localStorage.getItem(TOKEN_KEY);
19: }
20: 
21: /** Remove token (logout) */
22: export function clearToken(): void {
23:   localStorage.removeItem(TOKEN_KEY);
24: }
25: 
26: /**
27:  * Wrapper around fetch() that automatically attaches the JWT token
28:  * as an Authorization: Bearer header. Use this for ALL protected API calls.
29:  *
30:  * Usage:
31:  *   const res = await authFetch('/api/dashboard/stats');
32:  *   const data = await res.json();
33:  */
34: export async function authFetch(
35:   url: string,
36:   options: RequestInit = {}
37: ): Promise<Response> {
38:   const token = getToken();
39:   const headers = new Headers(options.headers || {});
40: 
41:   if (token) {
42:     headers.set('Authorization', `Bearer ${token}`);
43:   }
44: 
45:   // Ensure Content-Type is set for JSON bodies if not already
46:   if (options.body && !headers.has('Content-Type')) {
47:     headers.set('Content-Type', 'application/json');
48:   }
49: 
50:   return fetch(url, {
51:     ...options,
52:     headers,
53:   });
54: }
