"import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getAdminId } from "@/utils/serverAuth";
import countryCoords from "@/lib/country-coords.json";

type CountryCoordEntry = { lat: number; lng: number; name: string };
const coordsMap = countryCoords as Record<string, CountryCoordEntry>;

export async function GET() {
  const adminId = await getAdminId();
  if (!adminId)
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  // Aggregate security logs by countryCode
  const grouped = await prisma.securityLog.groupBy({
    by: ["countryCode"],
    where: {
      adminId,
      countryCode: { not: null },
    },
    _count: { id: true },
    orderBy: { _count: { id: "desc" } },
  });

  const threats = grouped
    .filter((g) => g.countryCode && g.countryCode !== "LO" && g.countryCode !== "?")
    .map((g) => {
      const code = g.countryCode!;
      const coords = coordsMap[code];
      return {
        countryCode: code,
        country: coords?.name || code,
        lat: coords?.lat || 0,
        lng: coords?.lng || 0,
        count: g._count.id,
      };
    })
    .filter((t) => t.lat !== 0 && t.lng !== 0);

  const totalAttacks = threats.reduce((sum, t) => sum + t.count, 0);

  return NextResponse.json({
    threats,
    totalCountries: threats.length,
    totalAttacks,
  });
}
"

"import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getAdminId } from "@/utils/serverAuth";

export async function GET(req: Request) {
  const adminId = await getAdminId();
  if (!adminId)
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const { searchParams } = new URL(req.url);
  const range = searchParams.get("range") || "24h";

  // Calculate the start date based on range
  const now = new Date();
  let startDate: Date;
  let bucketFormat: "hour" | "day";

  switch (range) {
    case "7d":
      startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
      bucketFormat = "day";
      break;
    case "30d":
      startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
      bucketFormat = "day";
      break;
    default: // 24h
      startDate = new Date(now.getTime() - 24 * 60 * 60 * 1000);
      bucketFormat = "hour";
      break;
  }

  // Fetch all logs within range
  const logs = await prisma.securityLog.findMany({
    where: {
      adminId,
      createdAt: { gte: startDate },
    },
    select: {
      createdAt: true,
      isBlocked: true,
      action: true,
    },
    orderBy: { createdAt: "asc" },
  });

  // Build time-series buckets
  const buckets = new Map<string, { safe: number; blocked: number }>();

  // Pre-fill buckets so chart has continuous data
  if (bucketFormat === "hour") {
    for (let i = 0; i < 24; i++) {
